i_rej = next(i for i, l in enumerate(lines_log) if l.startswith(REJ_ANCHOR))
out = lines_log[:i_rej] + acc_entries + [""] + lines_log[i_rej:]

open(P, "w", encoding="utf-8", newline="").write("\n".join(out))
print("OK 推演日志 +3，采纳 +3；行数", len(lines), "→", len(out))
